/* What Stripe is still asking a creator for, kept on their row so a reminder days later can read it: stripe_requirements (Stripe's own keys, like individual.verification.document), stripe_requirements_due_at (the date Stripe gave, when it gave one) and stripe_requirements_updated_at (when the account.updated webhook last wrote them). Only that webhook writes them, with the service role; an account Stripe has cleared gets an empty list, which is what ends a reminder sequence. Storelib knew this only for the seconds an account.updated webhook was being handled, so a notice could be sent once and never followed up; now lib/notify reads it again in the seconds before each follow-up sends (conditions.ts verification_still_needed), and says what is outstanding today instead of what a webhook said last week. Three columns on creators and nothing else: no row changes, no policy changes, no index. Nothing where there is no creators table. Needs nothing else. Until it runs, Stripe's asks are told once as before (PAYOUT_ACTION_REQUIRED, by email and in the bell) and the two follow-up reminders are planned and then skipped when they come due, because there is nothing recorded for them to read. Safe to run again. */
DO $$ BEGIN IF to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'stripe requirements: there is no creators table, nothing to do.'; ELSE ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_requirements text[]; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_requirements_due_at timestamptz; ALTER TABLE public.creators ADD COLUMN IF NOT EXISTS stripe_requirements_updated_at timestamptz; END IF; END $$;
DO $do$ BEGIN IF to_regprocedure('public.storelib_share_public_columns()') IS NOT NULL THEN PERFORM public.storelib_share_public_columns(); END IF; END $do$;
notify pgrst, 'reload schema';
